#!/usr/bin/env python3
"""Build a single, offline V3 financial scenario browser; no network or packages."""
from pathlib import Path
import json, csv, hashlib, argparse
from collections import defaultdict

BASE = Path(__file__).resolve().parents[1]
PROJECT = BASE.parent
parser = argparse.ArgumentParser()
parser.add_argument('--output', type=Path, default=PROJECT / 'deliverables' / 'Shenzhen_Eat_情景模拟_V3.html')
args = parser.parse_args()
report=BASE/'models'/'report_data_v3.json'; data=json.loads(report.read_text())
monthly_file=BASE/'models'/'monthly_v3.csv'
summary_fields='mode mode_name tier strategy scenario fitout equipment transfer preopening delivery_setup lease_deposit platform_deposit opening_inventory transfer_quote transfer_bundle_credit area_m2 initial_opening_outlay reserve initial_funding ref_partner_hour_each cash_shortfall_month capital_recovery_month all_funding_recovery_month staff_min staff_max mature_staff_m12 cumulative_business_cashflow total_capital_calls total_funding_with_calls cumulative_distributions partner_distribution_each cash_balance_m36'.split()
summary_fields += [f'y{n}_{s}' for n in [1,2,3] for s in ['recognized_revenue','operating_profit','business_cashflow','distributed_to_partners','avg_monthly_profit','avg_monthly_each_distribution']]
m_fields='month days paid_staff partner_count partner_daily_work_hours_each loaded_wage_per_staff addressable_opportunities returning_share conversion ramp season competition bottleneck available_person_min peak_person_min work_demand_person_min actual_person_min peak_actual_person_min equipment_capacity_day desired_total_daily realized_daily lost_daily_orders actual_onsite_daily actual_delivery_daily total_orders order_value_listed discounts refund_allowance recognized_revenue food_sold food_waste food_consumption packaging_cost platform_tech_fee merchant_delivery_cost payment_fee host_fee tax_risk_allowance gross_profit order_contribution contribution_per_order rent property_fee utilities_fixed other_fixed store_marketing platform_marketing staff_payroll owner_salary total_fixed_cost staff_change_cost operating_profit amortization accounting_profit inventory_change receivables_change maintenance_capex business_cashflow additional_capital distributed_to_partners distribution_per_partner retained_cash break_even_daily_orders break_even_cash_daily_orders'.split()
channel_fields='orders list_ticket_per_order discount_per_order refund_per_order revenue_per_order food_cost_per_order packaging_per_order platform_fee_per_order delivery_fee_per_order payment_fee_per_order host_fee_per_order tax_budget_per_order contribution_per_order'.split()
m_fields += [f'{c}_{v}' for c in ('onsite','meituan','taobao') for v in channel_fields]
compact_fields='month recognized_revenue operating_profit business_cashflow cumulative_business_cashflow retained_cash additional_capital distributed_to_partners paid_staff realized_daily'.split()
exit_fields='exit_month initial_funding additional_capital_before_exit cumulative_distributions remaining_cash lease_deposit_recovery platform_deposit_recovery equipment_recovery stock_recovery receivable_recovery transfer_recovery fitout_recovery asset_recovery_total lease_exit_charge staff_exit_cost clearance unsettled_misc exit_cost_total net_exit_payment_needed exit_day_bridge_before_recovery returned_cash_at_exit total_net_investor_loss loss_per_partner cash_payment_per_partner bridge_per_partner'.split()

def trim(row,keys):
    # Preserve complete raw numeric precision where meaningful, rounding only below sub-fen input precision.
    return {k:round(row[k], 6) if isinstance(row[k],float) else row[k] for k in keys}
cases={s['case_id']:{'s':trim(s,summary_fields),'m':[],'e':[]} for s in data['summary']}
for m in data['monthly_compact']:
    cases[m['case_id']]['m'].append([round(m[k],6) if isinstance(m[k],float) else m[k] for k in compact_fields])
for e in data['all_exits']:
    cases[e['case_id']]['e'].append(trim(e,exit_fields))
with monthly_file.open(encoding='utf-8-sig') as f:
    for r in csv.DictReader(f):
        if int(r['month'])==12:
            cases[r['case_id']]['m12']={k:r[k] if k=='bottleneck' else round(float(r[k]),6) if r[k] else None for k in m_fields}
assert len(cases)==135 and all(len(c['m'])==36 and len(c['e'])==4 and c['m12']['partner_count']==2 and c['m12']['owner_salary']==0 for c in cases.values())
for case in cases.values():
    s=case['s']; m=case['m12']; assert abs(s['initial_funding']-s['initial_opening_outlay']-s['reserve'])<.01
    assert abs(m['operating_profit']-(m['order_contribution']-m['total_fixed_cost']-m['staff_change_cost']))<.01
    for e in case['e']:
        assert abs(e['total_net_investor_loss']-(e['initial_funding']+e['additional_capital_before_exit']+e['net_exit_payment_needed']-e['cumulative_distributions']-e['returned_cash_at_exit']))<.01
sha=hashlib.sha256(report.read_bytes()).hexdigest()
source={'report_sha256':sha,'monthly_sha256':hashlib.sha256(monthly_file.read_bytes()).hexdigest(),'compact_fields':compact_fields,'cases':cases}
